mapper.select:
select count(1) cnt from MST_BOND_CREDIT_RATING T
where
	t.o_code = #{dto.oCode,jdbcType=VARCHAR}
	and t.GRADE_ORG_ID 	= #{dto.gradeOrgId,jdbcType=VARCHAR}
	and t.GRADE_DATE = 	#{dto.gradeDate, jdbcType=DATE}
	and t.O_TYPE = #{dto.oType, jdbcType=VARCHAR}
	and t.GRADE_RESULT = #{dto.gradeResult, jdbcType=VARCHAR}
	and t.SHORT_LONG_TERM = #{dto.shortLongTerm, jdbcType=VARCHAR}
